# -*- coding: utf-8 -*-
import re

from odoo import api, fields, models


class MrpProduction(models.Model):
    _inherit = 'mrp.production'

    # round_batch_id (round_management.StockFreshBoxWizard._compute_delivery_info)
    # reliably resolves the batch for MOs generated by the Pack Box wizard -
    # it regex-parses the sale order name out of the composed "origin"
    # string (e.g. "[Fresh] SO123 (Line 456) - Box 3/5"), unlike the
    # batch_id field added in round_management.stock_picking, which only
    # matches when origin equals a sale order name exactly. depot_id and
    # batch_delivery_date are exposed here (related, stored) so the
    # Production Report wizard/view can filter and group by them directly.
    depot_id = fields.Many2one(
        'stock.warehouse',
        string='Depot',
        related='round_batch_id.depot_id',
        store=True,
        readonly=True,
    )
    batch_delivery_date = fields.Date(
        string='Delivery Date',
        related='round_batch_id.delivery_date',
        store=True,
        readonly=True,
    )

    # Same "origin" string also carries the exact sale.order.line that this
    # box came from (the "(Line 456)" part) - used by the Production Report
    # (report/production_report.py) to attach each customer's special
    # requirements note to its own consolidated row, without merging it into
    # other customers' boxes of the same product/quantity.


